-- Demos Amnistia: catalogo separato dai voti, migrazione idempotente.
ALTER TABLE public.amnistia ADD COLUMN IF NOT EXISTS attiva boolean NOT NULL DEFAULT true, ADD COLUMN IF NOT EXISTS fonte_url text, ADD COLUMN IF NOT EXISTS precedente_storico text;
UPDATE public.amnistia SET attiva=false, descrizione='Reato abrogato dall''art. 1, comma 1, lett. b, legge 114/2024: non si applica una nuova amnistia alla fattispecie abrogata.' WHERE id=3 AND legge='Abuso d’ufficio';
UPDATE public.amnistia SET legge='Atti osceni presso luoghi frequentati da minori', articolo='Art. 527, comma 2, c.p.', descrizione='Punibile penalmente solo se commesso all''interno o nelle immediate vicinanze di luoghi abitualmente frequentati da minori e se ne deriva pericolo che vi assistano; la fattispecie generale è amministrativa.' WHERE id=4 AND legge='Atti osceni in luogo pubblico';
WITH proposte(legge, articolo, descrizione, fonte_url, precedente_storico) AS (VALUES ('Resistenza a pubblico ufficiale senza aggravanti gravi', 'Art. 337 c.p.', 'Amnistia limitata alle ipotesi senza aggravanti dell''art. 339 c.p. e senza lesioni gravi o gravissime né morte.', 'https://www.senato.it/legislature/17/leggi-e-documenti/disegni-di-legge/scheda-ddl?did=39319&tab=datiGenerali', 'DDL S.21/2013 (non vigente)'),
('Violenza o minaccia a pubblico ufficiale in casi non aggravati', 'Art. 336, comma 1, c.p.', 'Amnistia per ipotesi del primo comma, escluse aggravanti dell''art. 339 c.p., lesioni gravi o gravissime e morte.', 'https://www.senato.it/legislature/17/leggi-e-documenti/disegni-di-legge/scheda-ddl?did=39319&tab=datiGenerali', 'DDL S.21/2013 (non vigente)'),
('Rissa senza lesioni gravi o morte', 'Art. 588, comma 2, c.p.', 'Ipotesi del secondo comma limitate ai casi senza lesioni gravi o gravissime e senza morte.', 'https://www.senato.it/legislature/17/leggi-e-documenti/disegni-di-legge/scheda-ddl?did=39319&tab=datiGenerali', 'DDL S.21/2013 (non vigente)'),
('Furto aggravato con attenuanti specifiche', 'Artt. 624, 625 e 62 nn. 4 e 6 c.p.', 'Furto aggravato ai sensi dell''art. 625 quando ricorre almeno una delle attenuanti indicate nell''art. 62, nn. 4 e 6.', 'https://www.senato.it/legislature/17/leggi-e-documenti/disegni-di-legge/scheda-ddl?did=39319&tab=datiGenerali', 'DDL S.21/2013 (non vigente)'),
('Truffa aggravata in ipotesi delimitate', 'Art. 640, comma 2, c.p.', 'Amnistia proposta per ipotesi del secondo comma, escluse quelle con aggravante dell''art. 61, n. 7.', 'https://www.senato.it/legislature/17/leggi-e-documenti/disegni-di-legge/scheda-ddl?did=39319&tab=datiGenerali', 'DDL S.21/2013 (non vigente)'),
('Ricettazione di particolare tenuità', 'Art. 648 c.p. (oggi comma 4)', 'Il DDL S.21/2013 richiamava l''art. 648, comma 2, nel testo di allora. La particolare tenuità è ora disciplinata al comma 4.', 'https://www.senato.it/legislature/17/leggi-e-documenti/disegni-di-legge/scheda-ddl?did=39319&tab=datiGenerali', 'DDL S.21/2013 (non vigente)'),
('Falsa testimonianza su reati amnistiabili', 'Art. 372 c.p.', 'Amnistia proposta solo quando la testimonianza verte su un reato che rientra esso stesso nell''amnistia.', 'https://www.senato.it/legislature/17/leggi-e-documenti/disegni-di-legge/scheda-ddl?did=39319&tab=datiGenerali', 'DDL S.21/2013 (non vigente)'),
('Violazione di domicilio con violenza sulle cose', 'Art. 614, comma 4, c.p.', 'Amnistia limitata alla violenza sulle cose (non a tutte le forme di violazione di domicilio aggravata).', 'https://www.normattiva.it/eli/id/1990/04/12/090G0114/CONSOLIDATED/19970730', 'D.P.R. 75/1990 (precedente storico)'),
('Blocco stradale durante manifestazioni sindacali in casi non violenti', 'Art. 1, d.lgs. 66/1948', 'Precedente del 1990 per fatti legati a manifestazioni sindacali o gravi disagi, esclusi lesioni o morte e ulteriori aggravanti nei termini della norma.', 'https://www.normattiva.it/eli/id/1990/04/12/090G0114/CONSOLIDATED/19970730', 'D.P.R. 75/1990 (precedente storico)'),
('Diffamazione a mezzo stampa', 'Art. 595, comma 3, c.p.', 'Precedente del 1966 per diffamazione col mezzo della stampa, con le specifiche esclusioni richiamate dall''art. 596 c.p.', 'https://www.normattiva.it/atto/caricaDettaglioAtto?atto.codiceRedazionale=066U0332&atto.dataPubblicazioneGazzetta=1966-06-04', 'D.P.R. 332/1966 (precedente storico)')) INSERT INTO public.amnistia (legge, articolo, descrizione, fonte_url, precedente_storico, attiva) SELECT p.legge,p.articolo,p.descrizione,p.fonte_url,p.precedente_storico,true FROM proposte p WHERE NOT EXISTS (SELECT 1 FROM public.amnistia a WHERE lower(btrim(a.legge))=lower(btrim(p.legge)));
